USE sentinel_ai_security;
CREATE TABLE IF NOT EXISTS visitors (
    visitor_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, visitor_uuid CHAR(36) NOT NULL, company_id BIGINT UNSIGNED NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, contact_phone VARCHAR(30) NULL, contact_email VARCHAR(255) NULL, external_reference VARCHAR(100) NULL, visitor_status ENUM('ACTIVE','BLOCKED','ARCHIVED') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL,
    CONSTRAINT fk_visitors_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, UNIQUE KEY uq_visitors_uuid (visitor_uuid), INDEX idx_visitors_company_status (company_id,visitor_status), INDEX idx_visitors_company_name (company_id,last_name,first_name), INDEX idx_visitors_company_deleted_at (company_id,deleted_at)
);
CREATE TABLE IF NOT EXISTS visitor_visits (
    visitor_visit_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, visitor_id BIGINT UNSIGNED NOT NULL, site_id BIGINT UNSIGNED NOT NULL, host_employee_id BIGINT UNSIGNED NULL, authorized_by_user_id BIGINT UNSIGNED NULL, purpose VARCHAR(500) NOT NULL, planned_arrival_at DATETIME NULL, planned_departure_at DATETIME NULL, arrival_at DATETIME NULL, departure_at DATETIME NULL, visit_status ENUM('PRE_REGISTERED','AUTHORIZED','CHECKED_IN','CHECKED_OUT','CANCELLED','DENIED') NOT NULL DEFAULT 'PRE_REGISTERED', created_by_user_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_visitor_visits_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, CONSTRAINT fk_visitor_visits_visitor FOREIGN KEY (visitor_id) REFERENCES visitors(visitor_id) ON DELETE RESTRICT, CONSTRAINT fk_visitor_visits_site FOREIGN KEY (site_id) REFERENCES sites(site_id) ON DELETE RESTRICT, CONSTRAINT fk_visitor_visits_host FOREIGN KEY (host_employee_id) REFERENCES employees(employee_id) ON DELETE SET NULL, CONSTRAINT fk_visitor_visits_authorized_by FOREIGN KEY (authorized_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL, CONSTRAINT fk_visitor_visits_created_by FOREIGN KEY (created_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL,
    INDEX idx_visitor_visits_company_status (company_id,visit_status), INDEX idx_visitor_visits_company_site (company_id,site_id), INDEX idx_visitor_visits_company_arrival (company_id,arrival_at), INDEX idx_visitor_visits_company_visitor (company_id,visitor_id)
);